// STATE.md renderer (plans/README.md §7).

import {
  type PlanSet,
  STATUS_DONE,
  STATUS_IN_PROGRESS,
  STATUS_REVIEW,
  STATUS_BLOCKED,
  isStale,
  newest,
  claimableSet,
  byStatus,
  milestoneOrder,
  ownerName,
  blockedReason,
  formatStamp,
} from "./plan.ts";

// STATE_HEADER is the do-not-edit banner at the top of STATE.md.
const STATE_HEADER =
  "<!-- Generated by `node tools/plan/cli.ts state` from plans/PNN-*.md frontmatter. Do not edit by hand. -->";

// NONE is the placeholder used for empty sections.
const NONE = "_None._";

/** cell escapes a value for use inside a Markdown table cell. */
function cell(v: string): string {
  return v.replace(/\|/g, "\\|").replace(/\n/g, " ").trim();
}

/**
 * renderState renders STATE.md from the plan set.
 *
 * The renderer is deliberately clock-free: it contains no timestamps of its own and
 * derives the staleness marker from the newest `updated_at` in the set, so the same
 * plans/ directory always produces byte-identical output (plans/README.md §7).
 */
export function renderState(s: PlanSet): string {
  const ref = newest(s);
  let out = "";

  out += "# STATE.md — Claude Code Training\n\n";
  out += STATE_HEADER + "\n\n";

  // 1. TL;DR
  const milestones = milestoneOrder(s);
  const parts: string[] = [];
  for (const m of milestones) {
    let done = 0;
    let total = 0;
    for (const f of s.files) {
      if (f.meta.milestone !== m) continue;
      total++;
      if (f.meta.status === STATUS_DONE) done++;
    }
    parts.push(`**${m}** ${done}/${total} done`);
  }
  const claimable = claimableSet(s, ref);
  const ids = claimable.map((f) => f.meta.id);
  const wave = ids.length > 0 ? "`" + ids.join("`, `") + "`" : NONE;
  out +=
    `> **TL;DR:** ${parts.join(" · ")} · ${byStatus(s, STATUS_IN_PROGRESS).length} in progress · ` +
    `${byStatus(s, STATUS_REVIEW).length} in review · ${byStatus(s, STATUS_BLOCKED).length} blocked. ` +
    `Current wave (${claimable.length} claimable): ${wave}. Claim with \`node tools/plan/cli.ts claim PNN --owner <name>\`; ` +
    `regenerate this file with \`node tools/plan/cli.ts state\` — never hand-edit it.\n\n`;

  out += "---\n\n";

  // 2. Milestone progress
  out += "## Milestone progress\n\n";
  out += "| Milestone | done | review | in_progress | blocked | todo | total |\n";
  out += "|---|---:|---:|---:|---:|---:|---:|\n";
  for (const m of milestones) {
    const counts: Record<string, number> = {};
    let total = 0;
    for (const f of s.files) {
      if (f.meta.milestone !== m) continue;
      counts[f.meta.status] = (counts[f.meta.status] ?? 0) + 1;
      total++;
    }
    out += `| ${m} | ${counts[STATUS_DONE] ?? 0} | ${counts[STATUS_REVIEW] ?? 0} | ${counts[STATUS_IN_PROGRESS] ?? 0} | ${counts[STATUS_BLOCKED] ?? 0} | ${counts["todo"] ?? 0} | ${total} |\n`;
  }
  out += "\n";

  // 3. Claimable now
  out += "## Claimable now\n\n";
  if (claimable.length === 0) {
    out += NONE + "\n\n";
  } else {
    out += "| Plan | Title | model | effort | estimate |\n|---|---|---|---|---|\n";
    for (const f of claimable) {
      out += `| \`${f.meta.id}\` | ${cell(f.meta.title)} | ${f.meta.model_hint} | ${f.meta.effort_hint} | ${f.meta.estimate} |\n`;
    }
    out += "\n";
  }

  // 4. In progress
  out += "## In progress\n\n";
  const inProgress = byStatus(s, STATUS_IN_PROGRESS);
  if (inProgress.length === 0) {
    out += NONE + "\n\n";
  } else {
    out += "| Plan | Title | Owner | Branch | Since | Stale |\n|---|---|---|---|---|---|\n";
    for (const f of inProgress) {
      const marker = isStale(f, ref) ? "**STALE**" : "—";
      out += `| \`${f.meta.id}\` | ${cell(f.meta.title)} | ${cell(ownerName(f.meta))} | \`${f.meta.branch}\` | ${formatStamp(f.meta.updated_at)} | ${marker} |\n`;
    }
    out += "\nStale plans (no refresh for 24 h) may be reclaimed with `node tools/plan/cli.ts claim PNN --owner <name> --force`.\n\n";
  }

  // 5. Blocked
  out += "## Blocked\n\n";
  const blocked = byStatus(s, STATUS_BLOCKED);
  if (blocked.length === 0) {
    out += NONE + "\n\n";
  } else {
    out += "| Plan | Title | Owner | Reason |\n|---|---|---|---|\n";
    for (const f of blocked) {
      const reason = blockedReason(f) || "—";
      out += `| \`${f.meta.id}\` | ${cell(f.meta.title)} | ${cell(ownerName(f.meta))} | ${cell(reason)} |\n`;
    }
    out += "\n";
  }

  // 6. In review
  out += "## In review\n\n";
  const review = byStatus(s, STATUS_REVIEW);
  if (review.length === 0) {
    out += NONE + "\n\n";
  } else {
    out += "| Plan | Title | Owner | Branch |\n|---|---|---|---|\n";
    for (const f of review) {
      out += `| \`${f.meta.id}\` | ${cell(f.meta.title)} | ${cell(ownerName(f.meta))} | \`${f.meta.branch}\` |\n`;
    }
    out += "\n";
  }

  // 7. Done
  out += "## Done\n\n";
  let anyDone = false;
  for (const m of milestones) {
    const line: string[] = [];
    for (const f of s.files) {
      if (f.meta.milestone === m && f.meta.status === STATUS_DONE) line.push(`\`${f.meta.id}\``);
    }
    if (line.length > 0) {
      anyDone = true;
      out += `- **${m}** (${line.length}): ${line.join(", ")}\n`;
    }
  }
  if (!anyDone) out += NONE + "\n";
  out += "\n";

  // 8. Recent changes
  out += "## Recent changes\n\n";
  const recent = [...s.files]
    .sort((a, b) => {
      const ta = a.meta.updated_at.getTime();
      const tb = b.meta.updated_at.getTime();
      if (ta !== tb) return tb - ta;
      return a.meta.id < b.meta.id ? -1 : a.meta.id > b.meta.id ? 1 : 0;
    })
    .slice(0, 10);
  out += "| Plan | Status | Updated | Owner |\n|---|---|---|---|\n";
  for (const f of recent) {
    out += `| \`${f.meta.id}\` | ${f.meta.status} | ${formatStamp(f.meta.updated_at)} | ${cell(ownerName(f.meta))} |\n`;
  }
  out += "\n";

  // 9. Open questions
  out += "## Open questions\n\n";
  let wrote = false;
  for (const f of s.files) {
    for (const q of f.meta.open_questions) {
      if (q.trim() === "") continue;
      out += `- **${f.meta.id}** — ${q.trim()}\n`;
      wrote = true;
    }
  }
  if (!wrote) out += NONE + "\n";

  return out;
}
